const cityName = $input.item.json.cities;
const maxPages = $input.item.json.maxPages || 6;

if (!cityName) {
  throw new Error("cityName is required");
}

const searchQuery = `dentist near ${cityName}`;

const googleUrl = `https://www.google.com/search?q=${encodeURIComponent(searchQuery)}&sa=X&udm=1`;

return {
  json: {
    cityName,
    searchQuery,
    maxPages,
    googleUrl
  }
};

const cityName = $("Prepare Search").first().json.cityName;
const searchQuery = $("Prepare Search").first().json.searchQuery;
const currentPageData = $input.first().json.data.scrapeBusinesses.value;

const results = [];

try {
  const businesses = JSON.parse(currentPageData);
  businesses.forEach((business, businessIndex) => {
    results.push({
      cityName,
      searchQuery,
      page: $input.first().json.currentPage,
      index: businessIndex,
      title: business.title || "",
      address: business.address || "",
      rating: business.rating || "",
      reviews: business.reviews || "",
      phone: (business.phone || "").replace(/^\+/, ""),
      website: business.website || "",
      error: business.error || null
    });
  });
} catch (e) {
  results.push({
    cityName,
    searchQuery,
    page: $input.first().json.currentPage,
    index: 0,
    title: "",
    address: "",
    rating: "",
    reviews: "",
    phone: "",
    error: `Parse error: ${e.message}`
  });
}

return results.map(item => ({ json: item }));

